def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    groups = {}

    # Collect same-colored objects using diagonal connectivity.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                x, y = stack.pop()
                cells.append((x, y))
                for dx in (-1, 0, 1):
                    for dy in (-1, 0, 1):
                        nx, ny = x + dx, y + dy
                        if (0 <= nx < h and 0 <= ny < w and
                                (nx, ny) not in seen and grid[nx][ny] == color):
                            seen.add((nx, ny))
                            stack.append((nx, ny))
            groups.setdefault(color, []).append(cells)

    colors = list(groups)
    # The color whose objects are predominantly on the left stays in the left
    # half; the other color is placed in the right half.
    centers = {
        col: sum(c for cells in groups[col] for r, c in cells) /
             sum(len(cells) for cells in groups[col])
        for col in colors
    }
    colors.sort(key=lambda col: centers[col])
    out = [[0] * w for _ in range(h)]

    # Place each color's objects in its half, ordered top-to-bottom as
    # separate bottom-settled shapes.
    for idx, col in enumerate(colors):
        lo = 0 if idx == 0 else w // 2
        hi = w // 2 if idx == 0 else w
        objs = sorted(groups[col], key=lambda cells: min(r for r, c in cells))
        for cells in objs:
            mr = min(r for r, c in cells)
            mc = min(c for r, c in cells)
            shape = [(r - mr, c - mc) for r, c in cells]
            maxr = max(a for a, b in shape)
            maxc = max(b for a, b in shape)
            choices = []
            for top in range(h - maxr):
                for left in range(lo, hi - maxc):
                    pts = [(top + a, left + b) for a, b in shape]
                    if all(out[x][y] == 0 for x, y in pts):
                        choices.append((top, left, pts))
            if choices:
                _, _, pts = max(choices, key=lambda p: (p[0], -p[1]))
                for x, y in pts:
                    out[x][y] = col
    return out
